"""Robust client for the local order service (scratch tooling, not a deliverable)."""
import email.utils
import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
LOG_PATH = "/tmp/recon_work/http_log.jsonl"


def log(event):
    event["ts"] = time.time()
    with open(LOG_PATH, "a") as f:
        f.write(json.dumps(event) + "\n")


class NotFound(Exception):
    pass


class Client:
    def __init__(self, max_attempts=200):
        self.token = None
        self.max_attempts = max_attempts
        self.stats = {}

    def _bump(self, key):
        self.stats[key] = self.stats.get(key, 0) + 1

    def _raw(self, method, path, auth):
        if not path.startswith("/"):
            raise ValueError(f"refusing non-relative path {path!r}")
        req = urllib.request.Request(BASE + path, method=method)
        if auth:
            req.add_header("Authorization", f"Bearer {self.token}")
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, dict(resp.headers), resp.read()
        except urllib.error.HTTPError as e:
            body = e.read() if e.fp is not None else b""
            return e.code, dict(e.headers or {}), body

    @staticmethod
    def _retry_after(headers, body_json):
        """Seconds to wait as instructed by the server, or None if not stated."""
        ra = None
        for k, v in headers.items():
            if k.lower() == "retry-after":
                ra = v
        if ra is not None:
            try:
                return float(ra)
            except ValueError:
                dt = email.utils.parsedate_to_datetime(ra)
                return max(0.0, dt.timestamp() - time.time())
        if isinstance(body_json, dict):
            for key in ("retry_after", "retry_after_seconds", "wait", "wait_seconds", "retry_in"):
                if key in body_json:
                    return float(body_json[key])
        return None

    def refresh_token(self):
        for attempt in range(1, self.max_attempts + 1):
            try:
                status, headers, body = self._raw("POST", "/token", auth=False)
            except Exception as e:  # connection-level failure
                log({"kind": "conn_error", "path": "/token", "error": repr(e), "attempt": attempt})
                self._bump("conn_error")
                time.sleep(min(30, 0.5 * attempt))
                continue
            try:
                bj = json.loads(body) if body else None
            except ValueError:
                bj = None
            if status == 200 and isinstance(bj, dict) and isinstance(bj.get("token"), str):
                self.token = bj["token"]
                log({"kind": "token", "token": self.token})
                self._bump("token")
                return
            log({"kind": "http_error", "path": "/token", "status": status,
                 "headers": headers, "body": body.decode("utf-8", "replace")[:500], "attempt": attempt})
            self._bump(f"token_{status}")
            wait = self._retry_after(headers, bj)
            if wait is None:
                wait = min(30, 0.5 * attempt)
            time.sleep(wait + 0.05)
        raise RuntimeError("could not obtain token")

    def get(self, path, validate=None):
        """GET an authenticated JSON resource, retrying until a valid 200.

        Raises NotFound only after a 404 has been seen repeatedly (to rule out a transient 404).
        """
        if self.token is None:
            self.refresh_token()
        consecutive_404 = 0
        for attempt in range(1, self.max_attempts + 1):
            try:
                status, headers, body = self._raw("GET", path, auth=True)
            except Exception as e:
                log({"kind": "conn_error", "path": path, "error": repr(e), "attempt": attempt})
                self._bump("conn_error")
                time.sleep(min(30, 0.5 * attempt))
                continue
            text = body.decode("utf-8", "replace")
            try:
                bj = json.loads(body) if body else None
                parse_ok = True
            except ValueError:
                bj = None
                parse_ok = False

            if status == 200:
                problem = None
                if not parse_ok:
                    problem = "unparseable_json"
                elif validate is not None:
                    problem = validate(bj)
                if problem is None:
                    self._bump("ok")
                    if attempt > 1:
                        log({"kind": "recovered", "path": path, "attempt": attempt})
                    return bj
                log({"kind": "bad_200", "path": path, "problem": problem,
                     "headers": headers, "body": text[:2000], "attempt": attempt})
                self._bump("bad_200")
                time.sleep(min(10, 0.25 * attempt))
                continue

            log({"kind": "http_error", "path": path, "status": status, "headers": headers,
                 "body": text[:1000], "attempt": attempt})
            self._bump(f"http_{status}")

            if status == 401:
                self.refresh_token()
                continue
            if status == 404:
                consecutive_404 += 1
                if consecutive_404 >= 3:
                    raise NotFound(path)
                time.sleep(0.5)
                continue
            consecutive_404 = 0
            wait = self._retry_after(headers, bj)
            if wait is None:
                wait = min(30, 0.5 * attempt)
            time.sleep(wait + 0.05)
        raise RuntimeError(f"gave up on {path} after {self.max_attempts} attempts")


if __name__ == "__main__":
    c = Client()
    print(json.dumps(c.get(sys.argv[1]), indent=1)[:3000])
    print(c.stats, file=sys.stderr)

