"""Fetch each distinct customer referenced by the saved order pages exactly once; save to disk."""
import glob
import json
import sys

sys.path.insert(0, "/tmp/recon_work")
from client import Client, NotFound, log  # noqa: E402

RAW = sys.argv[1]
OUT = sys.argv[2]

ids = set()
for fn in glob.glob(f"{RAW}/page_*.json"):
    for it in json.load(open(fn))["items"]:
        ids.add(it["customer_id"])
ids = sorted(ids)
print("distinct customer ids:", len(ids), flush=True)


def validator(cid):
    def validate(bj):
        if not isinstance(bj, dict):
            return "not_a_dict"
        missing = {"id", "name", "region", "tier", "discount_pct"} - set(bj)
        if missing:
